77	    public void validate(@RequestBody RateRequest request, Out<RateInput> body)
78	            throws InvalidRateException {
79	        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
80	        if (!GRADES.contains(grade)) throw new InvalidRateException("A grade is one of A, B or C");
81	        String pct = request.pct() == null ? "" : request.pct().trim();
82	        if (pct.isEmpty()) throw new InvalidRateException("A rate is required");
83	        if (!PCT.matcher(pct).matches()) {
84	            throw new InvalidRateException("A rate is a percent of 0.00 or more, with up to two decimals");
85	        }
86	        LocalDate from = date(request.from(), "A from-date is a date, yyyy-MM-dd");
87	        LocalDate to = date(request.to(), "A to-date is a date, yyyy-MM-dd");
