216	/** The rates store: at most one rate per grade and from-date, kept per sheet. */
217	@Repository
218	public class RateRepository {
219	
220	    private static final RowMapper<Rate> ROW = (rs, n) -> new Rate(rs.getString("sheet_id"),
221	            rs.getString("grade"), rs.getBigDecimal("pct"), rs.getObject("from_date", LocalDate.class),
222	            rs.getObject("to_date", LocalDate.class));
223	
224	    private final JdbcTemplate jdbc;
225	
226	    public RateRepository(JdbcTemplate jdbc) {
227	        this.jdbc = jdbc;
228	    }
229	
230	    /**
231	     * The sheet's rates, by grade then from-date (none first), then those of its parent sheet and on
232	     * up to {@link Rate#MAX_LEVEL} levels, each at its level.
233	     */
234	    public List<Rate> findAll(String sheetId) {
235	        List<Rate> all = new ArrayList<>(findOwn(sheetId));
236	        List<String> ancestors = ancestors(sheetId);
237	        for (int i = 0; i < ancestors.size(); i++) {
238	            int level = i + 1;
239	            findOwn(ancestors.get(i)).forEach((r) -> all.add(r.up(level)));
240	        }
241	        return all;
242	    }
243	
244	    /** The sheet's parent, its parent's parent and so on, up to {@link Rate#MAX_LEVEL} of them. */
245	    private List<String> ancestors(String sheetId) {
246	        List<String> ancestors = new ArrayList<>();
247	        String at = sheetId;
248	        while (ancestors.size() < Rate.MAX_LEVEL) {
249	            List<String> parent = jdbc.query("SELECT parent_id FROM sheet WHERE id = ?",
250	                    (rs, n) -> rs.getString("parent_id"), at);
251	            if (parent.isEmpty() || parent.get(0) == null) break;
252	            at = parent.get(0);
253	            ancestors.add(at);
254	        }
255	        return ancestors;
256	    }
257	
258	    /** The rates set on the sheet itself, by grade then from-date (none first). */
259	    private List<Rate> findOwn(String sheetId) {
260	        return jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date FROM rate WHERE sheet_id = ?"
261	                + " ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
262	    }
263	
264	    /** Set the grade's rate from its from-date, replacing any it had for that from-date. */
265	    public void save(Rate rate) {
266	        jdbc.update("DELETE FROM rate WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
267	                rate.sheetId(), rate.grade(), rate.from());
268	        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)",
269	                rate.sheetId(), rate.grade(), rate.pct(), rate.from(), rate.to());
270	        jdbc.update("INSERT INTO rate_history (sheet_id, grade, pct, from_date, to_date, set_on)"
271	                + " VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
272	                rate.sheetId(), rate.grade(), rate.pct(), rate.from(), rate.to(), rate.sheetId());
273	    }
274	
275	    /**
276	     * The sheet's rates as they stood at the end of {@code day}: for each grade and from-date, the
277	     * last rate set for them while the sheet's today was on or before it; then its parent sheets'
278	     * (as they are named now) as they stood at the end of that day, each at its level.
279	     */
280	    public List<Rate> findAsOf(String sheetId, LocalDate day) {
281	        List<Rate> all = new ArrayList<>(findOwnAsOf(sheetId, day));
282	        List<String> ancestors = ancestors(sheetId);
283	        for (int i = 0; i < ancestors.size(); i++) {
284	            int level = i + 1;
285	            findOwnAsOf(ancestors.get(i), day).forEach((r) -> all.add(r.up(level)));
286	        }
287	        return all;
288	    }
289	
290	    private List<Rate> findOwnAsOf(String sheetId, LocalDate day) {
291	        Map<String, Rate> latest = new LinkedHashMap<>();
292	        jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date FROM rate_history WHERE sheet_id = ?"
293	                + " AND set_on <= ? ORDER BY id", (rs) -> {
294	                    Rate rate = ROW.mapRow(rs, 0);
295	                    latest.put(rate.grade() + "|" + rate.from(), rate);
296	                }, sheetId, java.sql.Date.valueOf(day));
297	        return new ArrayList<>(latest.values());
298	    }
