310	 * beginning of time) through a date (yyyy-MM-dd; '' when it has no end), and its level: 0 when set
311	 * on the sheet itself, 1 on its parent sheet, and so on up to MAX_LEVEL.
312	 */
313	export type Rate = { grade: Grade; pct: string; from: string; to: string; level: number };
