315	/** How many parent sheets up a rate is looked for. */
316	export const MAX_LEVEL = 3;
317	
318	export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;
319	
320	/** The sheet's rates, by grade then from-date (none first), then its parent sheets', each at its level. */
321	export function useRates(sheetId: string) {
322	  return useQuery({
323	    queryKey: ratesKey(sheetId),
324	    queryFn: async () =>
325	      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
326	  });
