329	/**
330	 * A grade's rate in force on a date (yyyy-MM-dd): the sheet's own, else its parent sheet's, and so
331	 * on up the levels. Null when no level has one in force.
332	 */
333	export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
334	  for (let level = 0; level <= MAX_LEVEL; level++) {
335	    const pct = rateAt(rates, grade, date, level);
336	    if (pct !== null) return pct;
337	  }
338	  return null;
