341	/**
342	 * A grade's rate in force on a date at one level: the one whose from-date is the latest on or
343	 * before it, unless its to-date is before the date. Null when the date is before every rate the
344	 * grade has there (or it has none), or after the to-date of the rate that would apply.
345	 */
346	function rateAt(rates: Rate[], grade: Grade, date: string, level: number): string | null {
347	  let best: Rate | null = null;
348	  for (const r of rates) {
349	    if ((r.level ?? 0) !== level || r.grade !== grade || r.from > date) continue;
350	    if (best === null || r.from > best.from) best = r;
351	  }
352	  if (best === null || (best.to !== '' && best.to < date)) return null;
353	  return best.pct;
354	}
