382	/** A two-decimal number (negative for a correction) as a whole count of hundredths. */
383	function hundredths(value: string): bigint {
384	  const trimmed = value.trim();
385	  const negative = trimmed.startsWith('-');
386	  const [whole, frac = ''] = (negative ? trimmed.slice(1) : trimmed).split('.');
387	  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
388	  return negative ? -cents : cents;
389	}
