396	/**
397	 * An amount times a rate, divided by 100, rounded to two decimals (half up when `halfUp`, else half
398	 * to even), raised to the sheet's `floor` when below it; n/a with no rate (no floor applies to n/a).
399	 * Worked in whole numbers so no floating-point error creeps in. A correction (a negative amount)
400	 * takes no floor (`floor` null).
401	 */
402	export function due(amount: string, pct: string | null, floor: string | null, halfUp: boolean): string {
403	  if (pct === null) return NA;
404	  const rounded = percentOf(amount, pct, 1n, halfUp);
405	  if (floor === null) return showCents(rounded);
406	  const least = hundredths(floor);
407	  return showCents(rounded < least ? least : rounded);
408	}
