410	/**
411	 * `times` × a percent of a two-decimal figure, in cents, rounded half up when `halfUp`, else half
412	 * to even (either symmetric about 0).
413	 */
414	function percentOf(figure: string, pct: string, times: bigint, halfUp: boolean): bigint {
415	  // cents × basis points is the due in millionths of a unit: 10000 of them to the cent.
416	  const signed = hundredths(figure) * hundredths(pct) * times;
417	  const x = signed < 0n ? -signed : signed;
418	  const cents = x / 10000n;
419	  const rest = x % 10000n;
420	  const rounded = rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n)) ? cents + 1n : cents;
421	  return signed < 0n ? -rounded : rounded;
